export const TYPES = ['rec', 'chapter', 'lff', 'general'];
export const TYPE_ICONS = {
  rec: 'fas fa-heart',
  chapter: 'fas fa-book-open',
  lff: 'fas fa-search',
  general: 'fas fa-comments'
};
export function typeLabel(app, type) {
  return app.translator.trans("ao3-companion.lib.type_".concat(type));
}
export function warningVocabulary(app) {
  return (app.forum.attribute('ao3Warnings') || '').split('\n').map(w => w.trim()).filter(Boolean);
}
flarum.reg.add('ao3-companion', 'common/ao3.jsao3', { TYPES: TYPES,TYPE_ICONS: TYPE_ICONS,typeLabel: typeLabel,warningVocabulary: warningVocabulary, });